import requests
from workflow_core import process_excel_to_mcp_direct

# 从上游节点获取 Excel 数据
excel_path = {{#workflow.excel_path#}}
sheet_name = {{#workflow.sheet_name#}}
serial = {{#workflow.serial#}}

# 生成 MCP 提示词
mcp_prompt = process_excel_to_mcp_direct(excel_path, sheet_name, serial)

# 返回给下游节点
return {"mcp_prompt": mcp_prompt}

result = {{#workflow.http_response#}}

if result.get('status') == 'success':
    return {"success": True, "message": "自动化执行成功", "logs": result.get('logs', [])}
else:
    return {"success": False, "message": result.get('message', '执行失败'), "error": result.get('error_details', {})}
